void rev(char *s, int n) {
    for (int i = 0; i < n / 2; i++) {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
}
int main(void) {
    char str[] = "program";
    int len = strlen(str);
    rev(str, 4);
    printf("%s\n", str);
    rev(str, len);
    printf("%s %c\n", str, str[len - 1]);
    return 0;
}

